import '../../../core/network/v2/api_v2_client.dart';
import '../../../core/network/v2/api_v2_constants.dart';
import '../../../core/network/v2/paginated.dart';
import '../../models/v2/buyer_order.dart';
import '../../models/v2/listing_summary.dart';

/// The buyer's own requests ("orders") and the suggestions curated for them.
///
/// Create payloads stay as maps because callers build them incrementally and
/// `submission_key` is generated by the screen, matching the owner listings
/// write flow.
class OrderServiceV2 {
  final ApiV2Client _client;

  OrderServiceV2({ApiV2Client? client}) : _client = client ?? ApiV2Client();

  Future<Paginated<BuyerOrder>> fetch({
    BuyerOrderStatus? status,
    ListingKind? type,
    String? listingType,
    String? cursor,
    int limit = ApiV2Constants.defaultLimit,
  }) {
    return _client.getCollection(
      ApiV2Constants.orders,
      parse: BuyerOrder.fromJson,
      query: {
        if (status != null && status != BuyerOrderStatus.unknown)
          'status': status.wireValue,
        if (type != null && type != ListingKind.unknown) 'type': type.name,
        if (listingType != null && listingType.isNotEmpty)
          'listing_type': listingType,
        if (cursor != null && cursor.isNotEmpty) 'cursor': cursor,
        'limit': _clampLimit(limit),
      },
    );
  }

  Future<BuyerOrder> fetchOrder(int id) async {
    final data = await _client.getItem(ApiV2Constants.order(id));
    return BuyerOrder.fromJson(data);
  }

  /// Create a buyer request. Reusing the same `submission_key` returns the
  /// existing order instead of consuming quota again.
  Future<BuyerOrder> create(Map<String, dynamic> payload) async {
    final data = await _client.sendItem(
      ApiV2Constants.orders,
      method: 'POST',
      body: payload,
    );

    return BuyerOrder.fromJson(data);
  }

  /// Cancel an active request. The backend treats a repeat as success.
  Future<BuyerOrder> cancel(int id) async {
    final data = await _client.sendItem(
      ApiV2Constants.orderCancel(id),
      method: 'POST',
    );

    return BuyerOrder.fromJson(data);
  }

  Future<Paginated<OrderSuggestion>> fetchSuggestions(
    int orderId, {
    String? cursor,
    int limit = ApiV2Constants.defaultLimit,
  }) {
    return _client.getCollection(
      ApiV2Constants.orderSuggestions(orderId),
      parse: OrderSuggestion.fromJson,
      query: {
        if (cursor != null && cursor.isNotEmpty) 'cursor': cursor,
        'limit': _clampLimit(limit),
      },
    );
  }

  /// Accept a suggestion; the backend creates one interest lead and returns
  /// the current state, so a repeat is safe.
  Future<OrderSuggestion> acceptSuggestion(
    int orderId,
    int suggestionId,
  ) async {
    final data = await _client.sendItem(
      ApiV2Constants.orderSuggestionAccept(orderId, suggestionId),
      method: 'POST',
    );

    return OrderSuggestion.fromJson(data);
  }

  /// Decline a suggestion; the backend treats a repeat as success.
  Future<OrderSuggestion> declineSuggestion(
    int orderId,
    int suggestionId,
  ) async {
    final data = await _client.sendItem(
      ApiV2Constants.orderSuggestionDecline(orderId, suggestionId),
      method: 'POST',
    );

    return OrderSuggestion.fromJson(data);
  }

  static int _clampLimit(int limit) {
    if (limit <= 0) return ApiV2Constants.defaultLimit;
    return limit > ApiV2Constants.maxLimit ? ApiV2Constants.maxLimit : limit;
  }
}
